G=load()

def f(grid):
    A=np.array(grid); H,W=A.shape
    out=A.copy()
    # find dividers: rows/cols that are constant and whose value differs from neighbors' dominant? use: constant rows/cols
    def regions(axis, sep_idx, n_segs=None):
        segs=[]; start=0
        for i in range(len(sep_idx)+1):
            s=start
            if i<len(sep_idx): s=sep_idx[i]+1
            e = sep_idx[i+1] if i+1<len(sep_idx) else (len(A) if axis==0 else W)
            segs.append((s,e))
        return segs
    # detect horizontal dividers: rows where all cells equal and that value repeats >=3? use rows fully constant with value appearing in a full row
    hdivs=[i for i in range(H) if len(set(A[i]))==1]
    vdivs=[j for j in range(W) if len(set(A[:,j]))==1]
    # partition into segments along each axis using dividers
    if len(hdivs)>0 and len(vdivs)>0:
        # cross layout: segments per axis combine into boxes
        hsegs=regions(0,hdivs); vsegs=regions(1,vdivs)
        boxes=[(hi,vi) for hi in hsegs for vi in vsegs]
        # patterned box = box containing non-bg cells (cells differing from bg of that box region...) 
        # bg = most common color overall excluding divider values
        vals,counts=np.unique(A,return_counts=True); bg=vals[counts.argmax()]
        divvals={A[i][j] for i in hdivs for j in range(W)}|{A[i][j] for j in vdivs for i in range(H)}
        pats=[]
        for hi,vi in boxes:
            sub=A[hi[0]:hi[1],vi[0]:vi[1]]
            if (sub!=bg).any(): pats.append((hi,vi))
        src=pats[0]
        si,sj=src[0],src[1]; e1,e2=src[1][0]-1,src[1][1]-1  # box extents
        for bi,bj in boxes:
            if (bi,bj)==src: continue
            b0,b1=bj[0],bj[1]
            for r in range(si[0],e1+1):
                for c in range(sj[0],e2+1):
                    rr=bi[0]+(r-si[0]); cc=bj[0]+(c-sj[0])
                    out[rr][cc]=A[r][c]
    elif len(vdivs)>0:
        vsegs=regions(1,vdivs)
        for i,(s,e) in enumerate(vsegs):
            for j,(s2,e2) in enumerate(vsegs):
                if i==j: continue
                for r in range(H):
                    for c in range(s,s2):
                        out[r][c]=A[r][s2+(c-s)]
    elif len(hdivs)>0:
        hsegs=regions(0,hdivs)
        for i,(s,e) in enumerate(hsegs):
            for j,(s2,e2) in enumerate(hsegs):
                if i==j: continue
                for r in range(s2,e2):
                    for c in range(W):
                        out[r][c]=A[s+(r-s2)][c]
    return out.tolist()

